    return { used: used, limit: limit, percent: used == null ? null : Math.min(100, used * 100 / limit), label: used == null ? "Пока нет данных о расходе токенов" : used.toLocaleString("ru-RU") + " из " + limit.toLocaleString("ru-RU") + " токенов" };
