    if (sub === "abilities") body = '<p>Доступно в этом чате. Настройки — в Библиотеке.</p><h3>Навыки · 2</h3>' + P.info("Анализ продаж", "Используется в текущем ответе", "spark", P.iconGo("Открыть навык Анализ продаж", "library/skill")) + P.info("Проверка таблиц", "Доступен", "spark") + '<h3>Инструменты · 3</h3>' + P.info("Чтение ресурсов", "Доступен", "search") + P.info("Форматирование таблицы", "Требует подтверждения", "code", P.iconGo("Открыть инструмент Форматирование таблицы", "library/tool")) + P.info("Работа с VBA", "Только связанный документ", "code") + '<h3>Правила</h3><p>Изменение документа требует подтверждения. Доступ ограничен документом этого чата.</p>';
